Implementation: extract a startCheck function with ref timer? useEffect with [] and internal function. Need no overlapping timers: use a ref to store timer, clear before setting new. Cleanup on unmount.

Design:

```tsx
import { useCallback, useEffect, useRef, useState } from 'react';

const DELAY = 120;

export function AsyncPanel() {
  const [state, setState] = useState<State>('loading');
  const timerRef = useRef<number | null>(null);

  const schedule = useCallback((next: State, delay: number) => {
    if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => {
      timerRef.current = null;
      setState(next);
    }, delay);
  }, []);

  useEffect(() => {
    const requested = new URLSearchParams(window.location.search).get('sync');
    schedule(requested === 'error' ? 'error' : 'success', DELAY);
    return () => {
      if (timerRef.current !== null) {
        window.clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [schedule]);

  const retry = () => {
    setState('loading');
    schedule('success', DELAY);
  };
  ...
  <button type="button" className="secondary" onClick={retry}>Retry sync</button>
```

